const API_BASE = "http://127.0.0.1:8000/api";

// Фабрика для створення контенту
export const contentFactory = (type, token) => {
  switch (type) {
    case "article":
      return async (articleData) => {
        const formData = new FormData();

        // Додаємо всі потрібні поля статті
        Object.entries(articleData).forEach(([key, value]) => {
          if (value !== undefined && value !== null) {
            if (key === "is_premium") {
              formData.append(key, value ? "true" : "false");
            } else {
              formData.append(key, value);
            }
          }
        });

        if (articleData.author) {
          formData.append("author", articleData.author);
        }

        const res = await fetch(`${API_BASE}/articles/`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
          body: formData,
        });

        if (!res.ok) {
          const errData = await res.json();
          console.error("📛 Помилка створення статті:", errData);
          throw new Error("Не вдалося створити статтю");
        }

        return await res.json();
      };

    case "poll":
      return async (pollData) => {
        // Створюємо Poll окремо, без Article
        const body = {
          question: pollData.question,
          choices: pollData.options.map((text) => ({ text })),
          channel: pollData.channel || null,
        };

        const res = await fetch(`${API_BASE}/polls/`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify(body),
        });

        if (!res.ok) {
          const errData = await res.json();
          console.error("📛 Помилка створення опитування:", errData);
          throw new Error("Не вдалося створити опитування");
        }

        return await res.json();
      };

    default:
      throw new Error("Невідомий тип контенту");
  }
};
